package android.app;import android.content.*;public class PendingIntent {public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=2;public Intent intent;public String type;public static PendingIntent getActivity(Context c,int id,Intent i,int f){return make(i,"activity");}public static PendingIntent getService(Context c,int id,Intent i,int f){return make(i,"service");}static PendingIntent make(Intent i,String t){PendingIntent p=new PendingIntent();p.intent=i;p.type=t;return p;} }